import { build } from 'esbuild'
import { readdir, readFile, writeFile } from 'node:fs/promises'
import { createHash } from 'node:crypto'

const result = await build({
  entryPoints: ['src/client/index.js'],
  bundle: true,
  format: 'cjs',
  target: 'es2022',
  platform: 'browser',
  // Keep module labels stable when a clean build shares the installed dependency directory.
  preserveSymlinks: true,
  loader: { '.css': 'text' },
  charset: 'utf8',
  external: ['react', 'react-dom', '@deepseek-ai/dsh-client-ui-primitives'],
  write: false,
})
const bundle = [
  '// Generated by npm run build.',
  'window.__ModuleLoader__.load({ id: "@dsh-plugins/nativecrew", factory(require) {',
  'const module = { exports: {} };',
  result.outputFiles[0].text,
  'return Object.defineProperty({ ...module.exports }, Symbol.toStringTag, { value: "Module" });',
  '} });',
].join('\n')
await writeFile('client.js', bundle + '\n')
// A mounted Host may outlive the archive installed on disk. Capture its build at module load for E2E checks.
const fingerprint = createHash('sha256')
const files = (await readdir('src', { recursive: true, withFileTypes: true }))
  .filter((entry) => entry.isFile())
  .map((entry) => entry.parentPath + '/' + entry.name)
  .filter((path) => !path.endsWith('/build-id.js'))
for (const entry of await readdir('computer-host', { recursive: true, withFileTypes: true })) {
  if (!entry.isFile()) continue
  const path = entry.parentPath + '/' + entry.name
  if (!path.includes('/test/') && /\.(?:js|mjs|go|mod|sum|swift|py|c|h|m|html)$/.test(path)) files.push(path)
}
files.push('package.json', 'cordis.patch.yml', 'client.js')
for (const entry of await readdir('bin', { withFileTypes: true })) {
  if (entry.isFile()) files.push('bin/' + entry.name)
}
for (const path of files.sort())
  fingerprint
    .update(path)
    .update('\0')
    .update(await readFile(path))
await writeFile(
  'src/host/build-id.js',
  'export const buildId = ' + JSON.stringify(fingerprint.digest('hex').slice(0, 16)) + '\n',
)
